import React, { useState } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext"; // 👈 1. Import Auth Context
import LogoutButton from "./LogoutButton"; // 👈 2. Import Logout Button

const Menu = () => {
  const { user } = useAuth(); // 👈 3. Get user data
  const [selectedMenu, setSelectedMenu] = useState(0);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);

  const handleMenuClick = (index) => setSelectedMenu(index);
  const handleProfileClick = () =>
    setIsProfileDropdownOpen(!isProfileDropdownOpen);

  const menuClass = "menu";
  const activeMenuClass = "menu selected";
  const userInitials = user ? user.slice(0, 2).toUpperCase() : "ZU";

  return (
    <div className="menu-container">
      <img src="logo.png" style={{ width: "50px" }} alt="Logo" />
      <div className="menus">
        <ul>
          {/* Navigation Links ... */}
          {[
            { to: "/", label: "Dashboard", id: 0 },
            { to: "/orders", label: "Orders", id: 1 },
            { to: "/holdings", label: "Holdings", id: 2 },
            { to: "/positions", label: "Positions", id: 3 },
            { to: "/funds", label: "Funds", id: 4 },
            { to: "/apps", label: "Apps", id: 6 },
          ].map((item) => (
            <li key={item.id}>
              <Link
                style={{ textDecoration: "none" }}
                to={item.to}
                onClick={() => handleMenuClick(item.id)}
              >
                <p
                  className={
                    selectedMenu === item.id ? activeMenuClass : menuClass
                  }
                >
                  {item.label}
                </p>
              </Link>
            </li>
          ))}
        </ul>
        <hr />
        {/* Profile Block with Dropdown */}
        <div style={{ position: "relative" }}>
          <div
            className="profile"
            onClick={handleProfileClick}
            style={{ cursor: "pointer" }}
          >
            <div className="avatar">{userInitials}</div>
            <p className="username">{user || "USERID"}</p>
          </div>
          {isProfileDropdownOpen && (
            <div style={styles.dropdownMenu}>
              <LogoutButton />
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// Add minimal styling to position the dropdown
const styles = {
  dropdownMenu: {
    position: "absolute",
    top: "45px",
    right: "0",
    backgroundColor: "white",
    border: "1px solid #ccc",
    padding: "10px",
    zIndex: 100,
  },
};

export default Menu;
